const onMouseMove = (e) => {
  // movementX/Y são unbounded (valem mesmo SEM pointer lock em browsers modernos).
  // Fallback clientX/clientY só quando movementX não é fornecido (limita na borda).
  if (e.movementX !== undefined) {
    input.mx += e.movementX; input.my += e.movementY;
  } else if (lastClientX !== null && lastClientY !== null) {
    input.mx += e.clientX - lastClientX;
    input.my += e.clientY - lastClientY;
  }
  lastClientX = e.clientX; lastClientY = e.clientY;
};

